window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b4b868bf1552558f"]={"versions": [{"id": "FIG-b4b868bf1552558f", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des E2E-Profils 7 (E2E Profile 7). Das Diagramm beschreibt den Teilschritt „Read DataID“ der Prüffunktion <code>E2E_P07Check()</code>, die als softwarebasierter Schutzmechanismus gegen Übertragungsfehler in sicherheitsrelevanten AUTOSAR-Kommunikationsbeziehungen (Classic und Adaptive Platform) eingesetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Aktivitätsbereich</strong>: <code>E2E_P07Check()</code> mit Subaktivitäts-/Call-Symbol.\n</li><li><strong>Eingangsdaten</strong>: Datenarray <code>Data[]</code> (Byte-Buffer der empfangenen Botschaft) an relativer Position <code>Offset + 16</code> bis <code>Offset + 19</code>.\n</li><li><strong>Lokale Zielvariable</strong>: <code>ReceivedDataID</code> vom Datentyp <code>uint32</code>.\n</li><li><strong>Aktion / Rechenknoten</strong>: <code>Copy bytes Data[Offset+16...Offset+19] in Big Endian order on uint32 local variable ReceivedDataID</code>.\n</li><li><strong>Ablaufknoten</strong>: Initialer Startknoten (Initial Node) und Aktivitätsendknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initial Node bei Eintritt in den Teilschritt „Read DataID“ innerhalb von <code>E2E_P07Check()</code>.\n</li><li>Über einen unbedingten Kontrollfluss wird die Aktion zum Extrahieren der Daten-ID ausgeführt: Vier aufeinanderfolgende Bytes aus dem Eingangsdatenstrom <code>Data</code> ab Index <code>Offset + 16</code> bis einschließlich <code>Offset + 19</code> werden in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die 32-Bit breite lokale Variable <code>ReceivedDataID</code> kopiert.\n</li><li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über, womit dieser Ausleseschritt beendet ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung [PRS_E2E_00499] ist dieses Verhalten normativ für die E2E-Profil-7-Prüfung vorgeschrieben. Entwickler müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>der Datenpuffer mindestens eine Länge von <code>Offset + 20</code> Bytes aufweist, um Pufferüberläufe zu verhindern,\n</li><li>die Konvertierung strikt in Big-Endian-Reihenfolge erfolgt, unabhängig von der nativen Endianness der Host-Plattform,\n</li><li>die extrahierte <code>ReceivedDataID</code> für nachfolgende Integritäts- und Echtheitsprüfungen (z. B. Abgleich mit der konfigurierten Soll-DataID) zur Verfügung steht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fe4b5ac9dc3c129e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des E2E-Profils 7 (E2E Profile 7). Das Diagramm beschreibt den Teilschritt „Read DataID“ der Prüffunktion <code>E2E_P07Check()</code>, die als softwarebasierter Schutzmechanismus gegen Übertragungsfehler in sicherheitsrelevanten AUTOSAR-Kommunikationsbeziehungen (Classic und Adaptive Platform) eingesetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Aktivitätsbereich</strong>: <code>E2E_P07Check()</code> mit Subaktivitäts-/Call-Symbol.\n</li><li><strong>Eingangsdaten</strong>: Datenarray <code>Data[]</code> (Byte-Buffer der empfangenen Botschaft) an relativer Position <code>Offset + 16</code> bis <code>Offset + 19</code>.\n</li><li><strong>Lokale Zielvariable</strong>: <code>ReceivedDataID</code> vom Datentyp <code>uint32</code>.\n</li><li><strong>Aktion / Rechenknoten</strong>: <code>Copy bytes Data[Offset+16...Offset+19] in Big Endian order on uint32 local variable ReceivedDataID</code>.\n</li><li><strong>Ablaufknoten</strong>: Initialer Startknoten (Initial Node) und Aktivitätsendknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initial Node bei Eintritt in den Teilschritt „Read DataID“ innerhalb von <code>E2E_P07Check()</code>.\n</li><li>Über einen unbedingten Kontrollfluss wird die Aktion zum Extrahieren der Daten-ID ausgeführt: Vier aufeinanderfolgende Bytes aus dem Eingangsdatenstrom <code>Data</code> ab Index <code>Offset + 16</code> bis einschließlich <code>Offset + 19</code> werden in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die 32-Bit breite lokale Variable <code>ReceivedDataID</code> kopiert.\n</li><li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über, womit dieser Ausleseschritt beendet ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung [PRS_E2E_00499] ist dieses Verhalten normativ für die E2E-Profil-7-Prüfung vorgeschrieben. Entwickler müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>der Datenpuffer mindestens eine Länge von <code>Offset + 20</code> Bytes aufweist, um Pufferüberläufe zu verhindern,\n</li><li>die Konvertierung strikt in Big-Endian-Reihenfolge erfolgt, unabhängig von der nativen Endianness der Host-Plattform,\n</li><li>die extrahierte <code>ReceivedDataID</code> für nachfolgende Integritäts- und Echtheitsprüfungen (z. B. Abgleich mit der konfigurierten Soll-DataID) zur Verfügung steht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b4b868bf1552558f", "to": "FIG-fe4b5ac9dc3c129e", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
